    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    threat_bids = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if opp.get('hp', 0) > 0 and opp.get('budget', 0) > 0:
                    threat_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_threat = max(threat_bids) if threat_bids else highest_prev
    avg_threat = sum(threat_bids) / len(threat_bids) if threat_bids else highest_prev

    units = int(supply // WATER_REQ)
    if units < 1:
        units = 1

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1

    if units <= 1:
        if danger >= 4:
            bid = max(highest_threat + 8.0, avg_threat + 10.0, 145.0)
        elif danger >= 2:
            bid = max(highest_threat + 3.0, avg_threat + 4.0, 115.0)
        else:
            bid = max(28.0, highest_threat * 0.32)
    else:
        if danger >= 4:
            bid = max(avg_threat + 2.0, 92.0)
        elif danger >= 2:
            bid = max(72.0, highest_threat * 0.72)
        else:
            bid = max(26.0, highest_threat * 0.22)

    if day >= 8 and hp > 5 and no_water_days == 0:
        bid *= 0.82

    if budget < bid:
        if danger >= 3:
            return float(budget)
        bid = max(0.0, min(budget, budget * 0.6))

    return float(min(budget, max(0.0, bid)))

