def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    # Basic sanity
    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0.0)
    no_water_days = my_status.get('no_water_days', 0)

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if budget <= 0:
        return 0.0

    # Reaction to yesterday: if any surviving opponent bid very high, we increase our bid.
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Pressure proxy
    pressure = 0.0
    if prev_bids:
        pressure = max(prev_bids)

    # Determine urgency from our hp/no_water_days
    # If we are close to death, bid aggressively.
    urgency = 0.0
    if hp <= 2:
        urgency = 1.0
    elif hp <= 4:
        urgency = 0.7
    elif hp <= 6:
        urgency = 0.4
    else:
        urgency = 0.2

    if no_water_days >= 2:
        urgency = max(urgency, 0.8)

    # Supply-based baseline: higher supply means we can bid less.
    # Use explicit int() for any indexing-like operations (none here), but keep safe.
    s = float(supply)
    if s <= MIN_SUPPLY:
        supply_factor = 1.0
    elif s >= MAX_SUPPLY:
        supply_factor = 0.7
    else:
        supply_factor = 1.0 - 0.3 * ((s - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))

    # If opponents were bidding near our daily salary, we must match more.
    # Otherwise, bid around mid level to secure water.
    if pressure >= DAILY_SALARY * 0.85:
        target = DAILY_SALARY * (0.55 + 0.45 * urgency) * supply_factor
    elif pressure >= DAILY_SALARY * 0.60:
        target = DAILY_SALARY * (0.45 + 0.35 * urgency) * supply_factor
    else:
        target = DAILY_SALARY * (0.35 + 0.45 * urgency) * supply_factor

    # Day-based slight ramp: later days need more survival.
    if isinstance(day, (int, float)):
        try:
            d = int(day)
        except Exception:
            d = 0
    else:
        d = 0
    if d >= 7:
        target *= 1.08
    elif d <= 2:
        target *= 0.95

    # Never exceed budget
    bid = min(float(budget), float(target))

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # Identify aggressive opponents from previous trace
    aggressive_bids = []
    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                aggressive_bids.append(prev['bid'])

    if aggressive_bids:
        max_prev = max(aggressive_bids)
        # If yesterday's max bid was high, be cautious unless we are desperate
        if max_prev > DAILY_SALARY * 1.0:
            if hp <= 2 or no_water_days >= 1:
                base = min(budget, DAILY_SALARY * 0.9)
            else:
                base = min(budget, DAILY_SALARY * 0.5)
        else:
            # Outbid yesterday's max by a small margin if we have health
            base = min(budget, max_prev + 2.0)
    else:
        # No previous bids: default moderate
        base = min(budget, DAILY_SALARY * 0.7)

    # Adjust for supply scarcity
    if supply < WATER_REQ * 2:
        # Water is scarce, need to bid higher to secure
        base = min(budget, base * 1.2)
    elif supply > WATER_REQ * 3:
        # Abundant water, can lower bid
        base = min(budget, base * 0.8)

    # Ensure we never bid more than budget
    bid = min(budget, base)
    # Prevent negative or zero bids when desperate
    if hp <= 2 or no_water_days >= 1:
        bid = max(bid, min(budget, DAILY_SALARY * 0.7))

    return bid
